"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9553],{59553:a=>{a.exports=JSON.parse('{"slug":"indeksaciya-pensiy-2027-fevral-aprel","locale":"ru","title":"Пенсии в 2027 году проиндексируют дважды, на 6,8% в феврале и на 3,3% в апреле","description":"Страховые пенсии в 2027 году повысят на 6,8% с 1 февраля и на 3,3% с 1 апреля. Как работает двойная индексация и сколько составит прибавка.","blocks":[{"id":"b001","kind":"paragraph","text":"Председатель Социального фонда Сергей Чирков назвал средний размер страховой пенсии по старости для неработающих в 2027 году: 30 241 рубль, на 2466 рублей больше, чем в 2026-м. Пенсии проиндексируют в два этапа. С 1 февраля на 6,8%, с 1 апреля ещё на 3,3%. Вместе это 10,3%. Индексация касается более 37 млн получателей страховых пенсий, и работающих пенсионеров тоже: им пенсии снова индексируют с 2025 года."},{"id":"b002","kind":"paragraph","text":"В 2026 году пенсии подняли один раз, на 7,6% с 1 января. Похожая схема из двух этапов, в феврале и апреле, была в законе до 2019 года, и теперь к ней возвращаются. У этапов разная логика. Февральский покрывает инфляцию за прошлый год, 6,8% это пока оценка, итог Росстат посчитает в январе. Апрельский зависит от доходов Социального фонда: если зарплаты и взносы с них растут быстрее цен, у фонда появляются деньги на прибавку сверх инфляции."},{"id":"b003","kind":"paragraph","text":"Представим, что зарплату поднимают раз в год, в феврале, ровно на ту инфляцию, которая уже случилась. Весь прошлый год цены росли, а доход стоял на месте, и к январю его хватало на меньшее. Февральская прибавка возвращает прежнюю покупательную способность, но не возмещает потерянного за год. Так устроена догоняющая индексация. С переносом даты на 1 февраля январь 2027 года пенсионеры проживут по ценам нового года на пенсию старого."},{"id":"b004","kind":"paragraph","text":"Отсюда и разница в цифрах. Если пенсия выросла на 10,3%, почему средняя прибавляет только 2466 рублей, около 9%? Потому что цифра 30 241 рубль означает среднюю пенсию за весь 2027 год. В январе она ещё прежняя, в феврале и марте с одной индексацией и только с апреля с обеими. По нашему расчёту, с апреля средняя пенсия неработающих будет около 30,6 тыс. рублей, примерно на 10% выше уровня 2026 года."},{"id":"b005","kind":"paragraph","text":"Реальная прибавка зависит от инфляции. Если в 2026 году цены вырастут на 6,8%, февральская индексация их только компенсирует, а апрельские 3,3% станут прибавкой сверх прошлогодней инфляции. Цены в 2027 году тоже будут расти, и часть этой прибавки съест уже новая инфляция. Аналитики, которых опрашивает Банк России, ждут по итогам 2026 года 7,1%. Февральская индексация идёт по фактической инфляции, поэтому при росте цен выше оценки она будет больше. Социальные пенсии индексируют отдельно, с 1 апреля, по росту прожиточного минимума, предварительно на 6,8%."},{"id":"b006","kind":"paragraph","text":"Работающим пенсионерам с 1 августа 2027 года ещё пересчитают пенсию с учётом взносов работодателя за 2026 год, но не больше чем на 3 пенсионных балла. Рублёвая прибавка у каждого своя и зависит от размера пенсии, её покажет личный кабинет Социального фонда. Проект бюджета фонда на 2027 год ещё должна принять Госдума. Апрельская прибавка заложена в него заранее, в расчёте на то, что зарплаты и взносы продолжат расти быстрее цен."},{"id":"b007","kind":"heading","text":"На сколько проиндексируют пенсии в 2027 году?"},{"id":"b008","kind":"paragraph","text":"Страховые пенсии повысят с 1 февраля на 6,8%, это оценка инфляции 2026 года, и с 1 апреля ещё на 3,3%. Вместе пенсия вырастет на 10,3%. Рублёвая прибавка у каждого своя и зависит от размера пенсии."},{"id":"b009","kind":"heading","text":"Проиндексируют ли пенсию работающим пенсионерам?"},{"id":"b010","kind":"paragraph","text":"Да. С 2025 года страховые пенсии индексируют и работающим пенсионерам, и обе индексации 2027 года их тоже касаются. Кроме того, с 1 августа им пересчитают пенсию с учётом взносов работодателя, но не больше чем на 3 пенсионных балла."},{"id":"b011","kind":"heading","text":"Почему средняя пенсия вырастет на 2466 рублей, а не на 10%?"},{"id":"b012","kind":"paragraph","text":"Цифра 30 241 рубль означает среднюю пенсию за весь 2027 год. В январе пенсия ещё прежняя, в феврале и марте с одной индексацией, и только с апреля с обеими. С апреля средняя пенсия неработающих будет около 30,6 тыс. рублей, примерно на 10% выше, чем в 2026 году."}],"sources":[{"label":"Средний размер страховой пенсии по старости повысится в 2027 году","url":"https://www.kommersant.ru/doc/9042520"},{"label":"Страховые пенсии в 2027 году проиндексируют дважды","url":"https://mintrud.gov.ru/pensions/94"},{"label":"Пенсии в 2027 году будут проиндексированы в феврале и апреле","url":"https://www.interfax.ru/russia/1119578"},{"label":"Страховые пенсии в 2027 году будут расти быстрее инфляции","url":"https://aif.ru/society/strahovye-pensii-v-2027-godu-budut-rasti-bystree-inflyacii"},{"label":"Пенсии в 2027 году. Двойная индексация, график повышений и новые суммы","url":"https://news.ru/economics/pensii-v-2027-godu-dvojnaya-indeksaciya-grafik-povyshenij-i-novye-summy"},{"label":"Макроэкономический опрос Банка России, октябрь 2026","url":"https://www.cbr.ru/content/document/file/193892/survey_pdf.pdf"},{"label":"Индексация пенсий в 2026 году","url":"https://www.banki.ru/webview/dialog/articles/40554/"},{"label":"Раскрыта сумма увеличения пенсий в России в 2027 году","url":"https://lenta.ru/news/2026/10/20/raskryta-summa-uvelicheniya-pensiy-v-rossii-v-2026-godu"},{"label":"Россиянам назвали средний размер страховой пенсии в 2027 году","url":"https://lenta.ru/news/2026/10/21/rossiyanam-nazvali-sredniy-razmer-strahovoy-pensii-v-2027-godu"}],"sourceBodySha256":"dbab3190117599a76dceb4c08cb97459487f6cc30b90ee5c5a928314ad375a22"}')}}]);